package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import static com.autocare.platform.order.ReservationStore.*;

/** Admission configuration, independent of invitation eligibility and case content. */
public class DiagnosisServicePolicies {
 final ReservationStore db;final OperatorIdentity operators;
 public DiagnosisServicePolicies(ReservationStore db,OperatorIdentity operators){this.db=db;this.operators=operators;}
 static org.springframework.web.server.ResponseStatusException conflict(){return new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"诊断服务配置、资格或版本已变化，请重新读取");}
 static JsonNode input(String raw,boolean update){var b=CouponInput.parse(raw);if(update)CouponInput.exact(b,"expected_revision","mode","source_note","valid_from","valid_to");else CouponInput.exact(b,"mode","source_note","valid_from","valid_to");if(update)CouponInput.version(b.get("expected_revision"));if(!Set.of("AVAILABLE","LEAVE_MESSAGE","PAUSED").contains(b.path("mode").asText()))throw ReservationInput.bad();text(b.get("source_note"),2,256);if(!CouponInput.time(b.get("valid_to")).isAfter(CouponInput.time(b.get("valid_from"))))throw ReservationInput.bad();return b;}
 static String text(JsonNode n,int min,int max){if(n==null||!n.isTextual())throw ReservationInput.bad();String s=n.textValue();if(!s.equals(s.strip())||s.codePointCount(0,s.length())<min||s.codePointCount(0,s.length())>max||s.codePoints().anyMatch(c->Character.isISOControl(c)||Character.getType(c)==Character.FORMAT||Character.getType(c)==Character.SURROGATE))throw ReservationInput.bad();return s;}
 void manage(OperatorActor a,boolean lock){operators.authorize(a,OperatorIdentity.Permission.DIAGNOSE_MANAGE,lock);}
 void guard(){db.one("SELECT id FROM diagnosis_control WHERE id=1 FOR UPDATE");}
 Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM diagnosis_service_policy WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 static Map<String,Object> view(Map<String,Object> r){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","revision","status","mode","source_note"))out.put(k,r.get(k));for(String k:List.of("valid_from","valid_to","created_at","published_at"))out.put(k,iso(r.get(k)));return out;}
 static Map<String,Object> availability(ReservationStore db){return availability(db,false);}
 static Map<String,Object> availability(ReservationStore db,boolean lock){
  var out=new LinkedHashMap<String,Object>();out.put("state","UNKNOWN");out.put("accepting",false);out.put("policy",null);var rows=db.jdbc.queryForList("SELECT * FROM diagnosis_service_policy WHERE status='PUBLISHED'"+(lock?" FOR UPDATE":""));if(rows.size()!=1)return out;var p=rows.get(0);out.put("policy",view(p));var now=db.now();String state=instant(p.get("valid_from")).isAfter(now)?"NOT_STARTED":!instant(p.get("valid_to")).isAfter(now)?"EXPIRED":"PAUSED".equals(p.get("mode"))?"PAUSED":(lock?db.jdbc.queryForList("SELECT id FROM operator_account WHERE status='ACTIVE' AND can_diagnose=1 FOR UPDATE").size():db.jdbc.queryForObject("SELECT COUNT(*) FROM operator_account WHERE status='ACTIVE' AND can_diagnose=1",Long.class))==0?"SOURCE_UNAVAILABLE":p.get("mode").toString();out.put("state",state);out.put("accepting",Set.of("AVAILABLE","LEAVE_MESSAGE").contains(state));return out;
 }
 public Map<String,Object> current(VehicleOwner a){return db.reads.execute(tx->{db.owner(a,false);return availability(db);});}
 public Map<String,Object> list(OperatorActor a,int page){return db.reads.execute(tx->{manage(a,false);long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM diagnosis_service_policy",Long.class);return page(db.jdbc.queryForList("SELECT * FROM diagnosis_service_policy ORDER BY id DESC LIMIT 20 OFFSET ?",(page-1)*20L).stream().map(DiagnosisServicePolicies::view).toList(),total,page,20);});}
 public Map<String,Object> handlers(OperatorActor a,int page){return db.reads.execute(tx->{manage(a,false);long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM operator_account WHERE status='ACTIVE' AND can_diagnose=1",Long.class);return page(db.jdbc.queryForList("SELECT id,account AS label FROM operator_account WHERE status='ACTIVE' AND can_diagnose=1 ORDER BY id LIMIT 20 OFFSET ?",(page-1)*20L),total,page,20);});}
 public JsonNode save(OperatorActor a,Long id,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),id==null?"POST":"PUT","/api/admin/diagnosis/policies"+(id==null?"":"/"+id),key,b,()->{manage(a,false);guard();manage(a,true);if(id!=null)row(id,true);},()->{
  Map<String,Object> before=Map.of();long target;if(id==null)target=db.insert("INSERT INTO diagnosis_service_policy(mode,source_note,valid_from,valid_to,created_by,created_at) VALUES(?,?,?,?,?,?)",b.path("mode").asText(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),a.id(),time(db.now()));else{var r=row(id,true);if(!"DRAFT".equals(r.get("status"))||number(r,"revision")!=b.path("expected_revision").asLong())throw conflict();before=view(r);target=id;db.jdbc.update("UPDATE diagnosis_service_policy SET mode=?,source_note=?,valid_from=?,valid_to=?,revision=revision+1 WHERE id=?",b.path("mode").asText(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),id);}if(!CouponInput.time(b.get("valid_to")).isAfter(db.now()))throw conflict();var after=view(row(target,true));return new Change("DIAGNOSIS_POLICY_SAVE","diagnosis_service_policy",target,before,after,after);
 });}
 public JsonNode status(OperatorActor a,long id,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/diagnosis/policies/"+id+"/status",key,b,()->{manage(a,false);guard();manage(a,true);row(id,true);},()->{
  var r=row(id,true);String to=b.path("status").asText();if(number(r,"revision")!=b.path("expected_revision").asLong()||!(to.equals("PUBLISHED")?"DRAFT".equals(r.get("status")):"STOPPED".equals(to)&&"PUBLISHED".equals(r.get("status"))))throw conflict();if(to.equals("PUBLISHED")&&(!instant(r.get("valid_to")).isAfter(db.now())||!db.jdbc.queryForList("SELECT id FROM diagnosis_service_policy WHERE status='PUBLISHED' FOR UPDATE").isEmpty()||!"PAUSED".equals(r.get("mode"))&&db.jdbc.queryForList("SELECT id FROM operator_account WHERE status='ACTIVE' AND can_diagnose=1 FOR UPDATE").isEmpty()))throw conflict();var before=view(r);db.jdbc.update("UPDATE diagnosis_service_policy SET status=?,revision=revision+1,published_at=? WHERE id=?",to,to.equals("PUBLISHED")?time(db.now()):r.get("published_at"),id);var after=view(row(id,true));return new Change("DIAGNOSIS_POLICY_STATUS","diagnosis_service_policy",id,before,after,after);
 });}
}
